    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    seq_counter = [0]

    def next_seq():
        seq_counter[0] += 1
        return seq_counter[0]

    def try_match(incoming_side, incoming_price, qty, incoming_is_market):
        # incoming_price is None for market orders (no price limit)
        nonlocal trades
        if incoming_side == 'buy':
            heap = sell_heap
        else:
            heap = buy_heap

        while qty > 0 and heap:
            top = heap[0]
            if incoming_side == 'buy':
                price_val, seq_val, oid = top
            else:
                neg_price, seq_val, oid = top
                price_val = -neg_price

            info = orders_info.get(oid)
            if info is None or info['status'] != 'resting':
                heapq.heappop(heap)
                continue

            # check price condition
            if not incoming_is_market:
                if incoming_side == 'buy':
                    if price_val > incoming_price:
                        break
                else:
                    if price_val < incoming_price:
                        break

            # pop it for processing
            heapq.heappop(heap)

            resting_qty = info['qty']
            trade_qty = min(qty, resting_qty)

            if incoming_side == 'buy':
                buy_id = None  # will set outside
            # determine buy_id, sell_id based on incoming_side
            # the resting order is opposite side
            if incoming_side == 'buy':
                # incoming is buy, resting is sell
                buy_id = incoming_id_holder[0]
                sell_id = oid
            else:
                buy_id = oid
                sell_id = incoming_id_holder[0]

            trades.append([buy_id, sell_id, price_val, trade_qty])

            qty -= trade_qty
            info['qty'] -= trade_qty

            if info['qty'] == 0:
                info['status'] = 'filled'
            else:
                # push back with same seq/price to maintain priority
                if incoming_side == 'buy':
                    heapq.heappush(heap, (price_val, seq_val, oid))
                else:
                    heapq.heappush(heap, (-price_val, seq_val, oid))
                # since resting order still has qty, and incoming still might have qty>0,
                # but resting order is now at front again; loop continues, but this order
                # was already checked, incoming still has qty to trade only if trade_qty==qty
                # actually if info['qty']>0, that means resting_qty > qty, so qty ==0 now, loop will end.
                pass

        return qty

    incoming_id_holder = [None]

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            _, oid = order
            info = orders_info.get(oid)
            if info is not None and info['status'] == 'resting':
                info['status'] = 'cancelled'
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
            incoming_id_holder[0] = oid
            remaining = try_match(side, price, qty, False)
            if remaining > 0:
                seq = next_seq()
                orders_info[oid] = {
                    'side': side,
                    'price': price,
                    'qty': remaining,
                    'seq': seq,
                    'status': 'resting'
                }
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, seq, oid))
                else:
                    heapq.heappush(sell_heap, (price, seq, oid))
            else:
                orders_info[oid] = {
                    'side': side,
                    'price': price,
                    'qty': 0,
                    'seq': next_seq(),
                    'status': 'filled'
                }

        elif typ == 'ioc':
            _, oid, side, price, qty = order
            incoming_id_holder[0] = oid
            remaining = try_match(side, price, qty, False)
            # discard remainder
            orders_info[oid] = {
                'side': side,
                'price': price,
                'qty': 0,
                'seq': next_seq(),
                'status': 'filled' if remaining == 0 else 'cancelled'
            }

        elif typ == 'market':
            _, oid, side, qty = order
            incoming_id_holder[0] = oid
            remaining = try_match(side, None, qty, True)
            orders_info[oid] = {
                'side': side,
                'price': None,
                'qty': 0,
                'seq': next_seq(),
                'status': 'filled' if remaining == 0 else 'cancelled'
            }

    return trades

